import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;public class FileTextDemo{public static void writeLines(Path p,List<String>l)throws IOException{Files.write(p,l,StandardCharsets.UTF_8);}public static List<String>readLines(Path p)throws IOException{return Files.readAllLines(p,StandardCharsets.UTF_8);}public static FileStats stats(Path p)throws IOException{String text=Files.readString(p,StandardCharsets.UTF_8);long words=Arrays.stream(text.split("\\s+")).filter(x->!x.isBlank()).count();return new FileStats(text.lines().count(),words,text.length());}public static void main(String[]a)throws Exception{Path p=Path.of("five-lines.txt");var l=List.of("HIT","Harare","Carlton","Tadiwa","Leo");writeLines(p,l);System.out.println(readLines(p));System.out.println(stats(p));Files.deleteIfExists(p);}}
